@startuml

class Animal {
  + ID
  + name
}

class Breed {
  + name
}

class Owner {
  + ID
  + name
  + address
  + phone
}

class Physician {
  + ID
  + name
  + address
  + phone
}

class Appointment {
  + date
  + time
}

class Condition {
  + common_name
  + scientific_name
}

Owner "0..1" -- "*" Animal : owns
Animal "1" -- "*" Appointment : attended by
Owner "1" -- "*" Appointment : attended by
Physician "1" -- "*" Appointment : responsible for
Appointment "*" -- "*" Condition : detects
Breed "1" -- "*" Animal : describes
Breed "1" -- "*" Condition : has common
@enduml

